use std::collections::HashMap;impl Solution{pub fn fraction_to_decimal(n:i32,d:i32)->String{if n==0{return"0".into()}let(mut a,mut b)=(n as i64,d as i64);let mut r=String::new();if(a<0)^(b<0){r.push('-')}a=a.abs();b=b.abs();r.push_str(&(a/b).to_string());let mut rem=a%b;if rem==0{return r}r.push('.');let mut m=HashMap::new();while rem!=0{if let Some(&p)=m.get(&rem){r.insert(p,'(');r.push(')');break}m.insert(rem,r.len());rem*=10;r.push(char::from(b'0'+(rem/b)as u8));rem%=b;}r}}
